def parse_query(query: str) -> dict:
    """Parse user query to extract intent and parameters"""
    query_lower = query.lower()

    # Check for prediction keywords
    if any(word in query_lower for word in ['predict', 'vs', 'versus', 'against']):
        # Extract team names (simplified)
        words = query.split()
        teams = [w for w in words if w[0].isupper() and len(w) > 2]
        return {
            'intent': 'prediction',
            'teams': teams[:2] if len(teams) >= 2 else [],
            'query': query
        }

    # Check for analysis keywords
    elif any(word in query_lower for word in ['analyze', 'analysis', 'performance', 'statistics']):
        words = query.split()
        teams = [w for w in words if w[0].isupper() and len(w) > 2]
        return {
            'intent': 'analysis',
            'team': teams[0] if teams else '',
            'query': query
        }

    return {
        'intent': 'unknown',
        'query': query
    }

def format_response(ai_analysis: str, match_data: dict) -> str:
    """Format the final response with tactical data and AI insights"""
    data_type = match_data.get('type', 'unknown')

    if data_type == 'prediction':
        data = match_data['data']
        pred = data.get('prediction', {})
        home_analysis = data.get('home_team_analysis', {})
        away_analysis = data.get('away_team_analysis', {})

        response = f"""🎯 Match Prediction with Tactical Analysis

Match: {data.get('match', 'N/A')}

Predicted Score: {pred.get('predicted_score', 'N/A')}
Probabilities:
- Home Win: {pred.get('home_win_probability', 0):.1f}%
- Draw: {pred.get('draw_probability', 0):.1f}%
- Away Win: {pred.get('away_win_probability', 0):.1f}%

Home Team Form: {home_analysis.get('form', {}).get('form_string', 'N/A')}
Away Team Form: {away_analysis.get('form', {}).get('form_string', 'N/A')}

AI Match Preview:
{data.get('ai_preview', {}).get('content', ai_analysis)}
"""

    elif data_type == 'analysis':
        data = match_data['data']
        stats = data.get('statistics', {})
        form = data.get('form', {})
        ai_insights = data.get('ai_insights', {})

        response = f"""📊 Team Performance Analysis with Tactical Data

Team: {data.get('team', 'N/A')}
Matches Analyzed: {data.get('matches_analyzed', 0)}

Key Statistics:
- Win Rate: {stats.get('win_rate', 0):.1%}
- Recent Form: {form.get('form_string', 'N/A')} (Score: {form.get('form_score', 0):.1f}/100)
- Goals Scored: {stats.get('goals_scored', 0)}
- Goals Conceded: {stats.get('goals_conceded', 0)}

AI Tactical Insights:
{ai_insights.get('content', ai_analysis)}

Generated by: {ai_insights.get('generated_by', 'IBM Granite 4.1 8B')}
"""

    else:
        response = f"Error: {match_data.get('message', 'Unknown error')}"

    return response
